  sum += textureLoad(
    sourceTexture,
    vec3<i32>(i32(sourceX0), i32(sourceY1), i32(sourceZ1)),
    0
  );
  sum += textureLoad(
    sourceTexture,
    vec3<i32>(i32(sourceX1), i32(sourceY1), i32(sourceZ1)),
    0
  );

